import{_ as e,o,c as l,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"IBM @ Ceph Day London","description":"","frontmatter":{"title":"IBM @ Ceph Day London","date":"2015-01-14T00:00:00.000Z","updated":"2015-01-14T00:00:00.000Z","tags":["Ceph","分布式存储","软件定义存储 (SDFS)","OpenStack","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/IBM_@_Ceph_Day_London.md","filePath":"posts/2015/IBM_@_Ceph_Day_London.md","lastUpdated":1780459816000}'),S={name:"posts/2015/IBM_@_Ceph_Day_London.md"};function p(a,t,i,_,s,r){return o(),l("div",null,[...t[0]||(t[0]=[n("<p>IBM 研究部门在 Ceph Day London 会议中分享了他们在软件定义存储（SDFS）领域的工作和未来规划。以下是会议的主要内容：</p><p><strong>IBM 研究部门在 SDFS 领域的工作</strong></p><ul><li>IBM 研究实验室专注于大规模存储和云计算解决方案，为研究人员提供本地数据中心和存储资源。</li><li>利用 OpenStack 和 SDFS 技术，为研究人员提供可定制的虚拟机和存储资源。</li><li>SDFS 部署经历两个阶段：初始使用 3 个计算节点和 14TB SSD 存储，后续采用 6 个节点，每个节点配备 12TB 硬盘，配置 1:4 的 SSD 与 HDD 混合存储。</li></ul><p><strong>SDFS 在 SoftLayer 的应用</strong></p><ul><li>SoftLayer 作为 IBM 的云服务平台，提供托管、管理和维护服务。</li><li>基于 SDFS 的托管、管理私有云存储服务，用户可选择存储容量和计算资源。</li><li>提供 1G 或 10G 网络连接，采用双副本复制机制保证数据可靠性。</li></ul><p><strong>SDFS 未来规划</strong></p><ul><li>增强安全性：引入虚拟机级别的 SDFS 认证机制，防止密钥泄露。</li><li>优化性能：提高虚拟机快照性能，减少数据传输时间，支持异步复制。</li><li>多数据中心管理：数据中心语义管理，跨数据中心资源分配和调度。</li></ul><p><strong>行动计划</strong></p><ul><li>IBM 研究部门将继续优化 SDFS 技术，并将其应用到更多场景中。</li><li>与 SDFS 社区合作，推动 SDFS 技术的进一步发展。</li><li>推出更多基于 SDFS 的云服务，满足用户需求。</li></ul><p><strong>关键词</strong>： Ceph, 分布式存储, 软件定义存储 (SDFS), OpenStack, 云计算, 高可用性, 可伸缩性, 安全性, 性能优化, 跨数据中心管理</p>",10)])])}const c=e(S,[["render",p]]);export{d as __pageData,c as default};
